(function () {
  'use strict';
  const registry = globalThis.MaddaTools = globalThis.MaddaTools || {};
  const S = () => globalThis.MaddaScience;
  const sub = value => String(value).replace(/[0-9]/g, d => '₀₁₂₃₄₅₆₇₈₉'[d]);
  const fml = value => String(value).replace(/([A-Za-z)])(\d+)/g, (_, atom, n) => atom + sub(n));
  const esc = value => String(value).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const bdi = value => `<bdi dir="ltr">${esc(value)}</bdi>`;
  const signed = (value,ctx) => (value>0?'+':value<0?'−':'')+ctx.fa(Math.abs(value),0);
  const svg = (label, body, height = 310, scene = '') => `<svg class="mt-svg ${scene}" viewBox="0 0 620 ${height}" role="img" aria-label="${esc(label)}" xmlns="http://www.w3.org/2000/svg">${body}</svg>`;
  const txt = (x, y, value, cls = '', anchor = 'middle') => `<text x="${x}" y="${y}" text-anchor="${anchor}" class="${cls}">${esc(value)}</text>`;
  const line = (x1,y1,x2,y2,cls='') => `<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" class="${cls}"${cls.includes('mt-draw')?' pathLength="1"':''}/>`;
  const sequence = (body, index, cls, delay = 55) => `<g class="${cls}" style="--stagger:${index*delay}ms">${body}</g>`;
  const metric = (label, value, unit = '') => `<div class="metric"><div class="metric-value">${bdi(value)} <span class="mt-unit">${bdi(unit)}</span></div><div class="metric-label">${esc(label)}</div></div>`;
  const analysis = (title, body, note='') => `<section class="mt-analysis"><h3>${title}</h3>${body}${note?`<details class="mt-analysis-limit"><summary>دربارهٔ نمودار</summary><p class="mt-hint">${note}</p></details>`:''}</section>`;
  const legend = (a,b) => `<div class="mt-chart-legend"><span class="mt-legend-a">${a}</span><span class="mt-legend-b">${b}</span></div>`;
  function structure(model) {
    const n=model.carbons,ring=model.family==='cycloalkane',multiple=model.family==='alkene'?2:model.family==='alkyne'?3:1;
    const bonds=Array(Math.max(0,n-(ring?0:1))).fill(1);if(multiple>1)bonds[model.position]=multiple;
    const h=Array(n).fill(4);bonds.forEach((order,i)=>{h[i]-=order;h[(i+1)%n]-=order;});
    return {bonds,h,key:model.family+':'+n+':'+(multiple>1?Math.min(model.position,n-2-model.position):0),condensed:ring?'(CH₂)'+sub(n):h.map((count,i)=>(i?['','–','=','≡'][bonds[i-1]]:'')+'C'+(count?'H'+(count>1?sub(count):''):'')).join('')};
  }
  function choices(key, label, options) {
    return `<fieldset class="control-group mt-fieldset"><legend class="control-label">${label}</legend><div class="choice-group">${options.map(([v,t])=>`<button type="button" class="choice-button" data-key="${key}" data-value="${v}" aria-pressed="false">${t}</button>`).join('')}</div></fieldset>`;
  }
  function range(key,label,min,max,value,step=1,unit='') {
    return `<div class="control-group"><label class="control-label" for="mt-${key}">${label} <output data-output="${key}" for="mt-${key}"></output></label><div class="range-row"><input id="mt-${key}" type="range" data-range="${key}" min="${min}" max="${max}" value="${value}" step="${step}" aria-label="${label}"><span class="mt-unit">${unit}</span></div></div>`;
  }
  function frame(label, controls, note) {
    const scenes={
      'ساختار هیدروکربن':['molecules','از ظرفیت کربن، ساختار بساز','اتم‌ها را بشمار؛ جای پیوند را عوض کن.'],
      'گرماسنج دو نمونه':['heat','گرمای برابر، پاسخ متفاوت','جرم و جنس را تغییر بده؛ دماها را مقایسه کن.'],
      'جمع واکنش‌ها':['hess','هر مسیر، یک حساب انرژی','پله‌ها را عوض کن تا مواد اضافه حذف شوند.'],
      'سرعت متوسط واکنش':['rates','بین دو اندازه‌گیری مکث کن','بازهٔ انتخابی و شیب آن را کنار هم ببین.'],
      'ساخت زنجیر بسپار':['polymers','پیوند تازه، زنجیر بلندتر','گروه جانبی را هنگام اتصال دنبال کن.'],
      'برج تقطیر نفت خام':['refinery','از بخار تا برش نفتی','مسیر جداسازی را در برج دنبال کن.'],
      'مقایسهٔ عنصرها':['periodic','یک جدول، الگوهای تکرارشونده','دو عنصر را انتخاب کن و لایه‌ها را مقایسه کن.']
    };
    const scene=scenes[label]||['default',label,''];
    return `<div class="tool-layout mt-tool mt-feature-${scene[0]}"><div class="tool-stage mt-stage"><div class="mt-scene-caption"><strong>${scene[1]}</strong></div><div class="mt-scene" aria-label="${label}"></div><div class="mt-result"></div></div><section class="tool-controls mt-controls" aria-label="کنترل‌های ${label}">${controls}<div class="tool-actions"><button type="button" class="btn btn-primary" data-action="save">ثبت در دفتر</button><button type="button" class="btn btn-secondary" data-action="reset">از نو</button></div><details class="mt-model-limit"><summary>محدودهٔ مدل</summary><p class="model-note">${note}</p></details></section></div>`;
  }
  function bind(container, ctx, state, defaults, update, save, extra) {
    const sync = () => {
      container.querySelectorAll('[data-key]').forEach(b=>{const active=String(state[b.dataset.key])===b.dataset.value;b.classList.toggle('selected',active);b.setAttribute('aria-pressed',String(active));});
      container.querySelectorAll('[data-range]').forEach(i=>{i.value=state[i.dataset.range];const o=container.querySelector(`[data-output="${i.dataset.range}"]`);if(o)o.textContent=ctx.fa(state[i.dataset.range],Number(i.step)<1?1:0);});
    };
    const refresh = () => {
      const focused=document.activeElement,action=focused&&container.contains(focused)?focused.dataset.action:null;
      const focusId=action==='element'?focused.dataset.z:action==='bond'?focused.dataset.index:null;
      const scroller=container.querySelector('.mt-periodic-scroll'),scroll=scroller?scroller.scrollLeft:0;
      sync();update();
      const nextScroller=container.querySelector('.mt-periodic-scroll');if(nextScroller)nextScroller.scrollLeft=scroll;
      if(focusId!==null){const next=container.querySelector(action==='element'?`[data-action="element"][data-z="${focusId}"]`:`[data-action="bond"][data-index="${focusId}"]`);if(next)next.focus({preventScroll:true});}
    };
    const click = event => {
      const b=event.target.closest('button'); if(!b||!container.contains(b)||b.disabled)return;
      if(b.dataset.action==='reset'){Object.assign(state,defaults);if(extra)extra('reset');refresh();ctx.announce('آزمایش به حالت آغاز برگشت.');}
      else if(b.dataset.action==='save')save();
      else if(b.dataset.key){state[b.dataset.key]=b.dataset.value;if(extra)extra(b.dataset.key,b.dataset.value);refresh();}
      else if(extra){extra('action',b.dataset.action,b);refresh();}
    };
    const input = event => {const i=event.target;if(!i.dataset.range)return;state[i.dataset.range]=Number(i.value);if(extra)extra(i.dataset.range,state[i.dataset.range]);refresh();};
    container.addEventListener('click',click);container.addEventListener('input',input);refresh();
    return ()=>{container.removeEventListener('click',click);container.removeEventListener('input',input);};
  }
  function bondsPath(points,bonds,closed) {
    let body='';
    for(let i=0;i<bonds.length;i++){
      const a=points[i],b=points[(i+1)%points.length],dx=b[0]-a[0],dy=b[1]-a[1],len=Math.hypot(dx,dy),nx=-dy/len,ny=dx/len;
      let bond='';for(let j=0;j<bonds[i];j++){const off=(j-(bonds[i]-1)/2)*6;bond+=line(a[0]+nx*off,a[1]+ny*off,b[0]+nx*off,b[1]+ny*off,'mt-bond mt-draw');}body+=sequence(bond,i,'mt-build-bond');
    }
    return body;
  }

  registry.molecules={title:'سازندهٔ هیدروکربن',chapter:1,pages:'۳۱ تا ۴۳',mount(container,ctx){
    const defaults={family:'alkane',carbons:4,position:0,basis:'mass'},state={...defaults};
    let reference={family:'alkane',carbons:3,position:0};
    const families={alkane:'آلکان',alkene:'آلکن',alkyne:'آلکین',cycloalkane:'سیکلوآلکان'};
    container.innerHTML=frame('ساختار هیدروکربن',choices('family','خانواده',Object.entries(families))+range('carbons','تعداد کربن',1,10,4)+`<div class="control-group"><span class="control-label">جای پیوند چندگانه</span><div class="mt-bond-choices"></div><p class="mt-hint">در زنجیر سیرنشده، جای پیوند ویژه را انتخاب کنید.</p></div>`+choices('basis','ترکیب را بر چه اساسی مقایسه کنیم؟',[['mass','جرم C و H'],['atoms','تعداد اتم‌ها']])+`<button type="button" class="btn btn-secondary" data-action="pin">نگه‌داشتن این ساختار برای مقایسه</button>`, 'مدل اتصال اتم‌هاست؛ زاویه‌ها و طول پیوندها هندسهٔ واقعی مولکول نیستند. سوختن کامل با اکسیژن کافی محاسبه می‌شود.');
    let result;
    const update=()=>{
      const n=state.carbons,ring=state.family==='cycloalkane',multiple=state.family==='alkene'?2:state.family==='alkyne'?3:1;
      container.querySelector('[data-range="carbons"]').min=state.family==='alkane'?1:ring?3:2;
      result=S().hydrocarbon({carbons:n,family:state.family});
      const {bonds,h,condensed}=structure(state);
      const points=Array.from({length:n},(_,i)=>ring?[310+100*Math.cos(-Math.PI/2+i*2*Math.PI/n),155+100*Math.sin(-Math.PI/2+i*2*Math.PI/n)]:[n===1?310:48+i*524/(n-1),130+(i%2)*44]);
      let body=bondsPath(points,bonds,ring);
      points.forEach(([x,y],i)=>{body+=sequence(`<circle cx="${x}" cy="${y}" r="20" class="mt-carbon"/>`+txt(x,y+6,'C','mt-atom-letter')+txt(ring?310+(x-310)*1.35:x,ring?155+(y-155)*1.35+6:y+43,h[i]?'H'+(h[i]>1?sub(h[i]):''):'','mt-hydrogen')+(ring?'':txt(x,y-28,String(i+1),'mt-svg-small')),i,'mt-build-atom');});
      body+=txt(310,ring?340:265,result.displayFormula||fml(result.formula),'mt-svg-formula');
      container.querySelector('.mt-scene').innerHTML=svg(`ساختار ${n} کربنی با ${result.hydrogens} هیدروژن؛ ظرفیت همهٔ کربن‌ها چهار است.`,body,ring?365:330,'mt-molecule-scene');
      container.querySelector('.mt-result').innerHTML=`<p class="mt-hint">${ring?'ساختار حلقوی؛ دو سر زنجیر به هم وصل‌اند:':'فرمول ساختاری فشرده؛ ترتیب کربن‌ها از چپ به راست:'}</p><div class="mt-equation mt-condensed">${bdi(condensed)}</div><div class="metric-grid">${metric('جرم مولی',ctx.fa(result.molarMass,0),'g/mol')}${metric('هیدروژن کل',ctx.fa(result.hydrogens,0))}${metric('ظرفیت هر کربن','۴')}</div><p class="mt-proof">${ctx.fa(n,0)} کربن بررسی شد؛ مجموع مرتبهٔ پیوندها و پیوند با هیدروژن برای هر کربن ۴ است.</p><div class="mt-equation">${bdi((result.displayFormula||fml(result.formula))+' + '+result.oxygen+'O₂ → '+result.carbonDioxide+'CO₂ + '+result.water+'H₂O')}</div><p class="explanation">${families[state.family]}${ring?' یک حلقه با پیوندهای یگانه دارد.':multiple>1?' در این مدل یک پیوند '+(multiple===2?'دوگانه':'سه‌گانه')+' دارد؛ هیدروژن‌های دو کربنِ درگیر کمترند.':' در این مدل زنجیری باز با پیوندهای یگانه دارد.'}</p>`;
      const ref=S().hydrocarbon(reference),mass=state.basis==='mass';
      const composition=(model,r,label)=>{const c=r.carbons*(mass?12:1),h=r.hydrogens,total=c+h,pct=100*c/total;return `<div class="mt-composition-row"><div class="mt-comparison-label"><strong>${label} · ${bdi(r.displayFormula||fml(r.formula))}</strong><span>${families[model.family]}</span></div><div class="mt-comparison-formula">${bdi(structure(model).condensed)}</div><div class="mt-composition-track" role="img" aria-label="سهم کربن ${ctx.fa(pct,1)} درصد؛ سهم هیدروژن ${ctx.fa(100-pct,1)} درصد"><span class="mt-composition-c" style="width:${pct}%"></span><span class="mt-composition-h" style="width:${100-pct}%"></span></div><p class="mt-bar-values">${bdi('C: '+ctx.fa(c,0)+(mass?' g/mol':''))} · ${bdi('H: '+ctx.fa(h,0)+(mass?' g/mol':''))} <strong>سهم کربن: ${ctx.fa(pct,1)}٪</strong></p></div>`;};
      container.querySelector('.mt-result').innerHTML+=analysis('دو ساختار، دو ترکیب',legend('کربن','هیدروژن')+composition(state,result,'در حال ساخت')+composition(reference,ref,'ساختار مرجع')+`<p class="mt-comparison-conclusion">${result.formula===ref.formula?(structure(state).key===structure(reference).key?'ساختار و فرمول مرجع با نمونهٔ فعلی یکسان است.':'فرمول مولکولی یکسان است، اما اتصال اتم‌ها فرق دارد؛ درصد جرمی به‌تنهایی ساختار را تعیین نمی‌کند.'):`تفاوت هیدروژن: ${bdi(signed(result.hydrogens-ref.hydrogens,ctx))}؛ تفاوت جرم مولی: ${bdi(signed(result.molarMass-ref.molarMass,ctx)+' g/mol')}`}</p>`,mass?'عرض نوارها سهم جرمی است؛ با جرم اتمی آموزشی C=12 و H=1 محاسبه شده.':'عرض نوارها سهم تعداد اتم‌هاست؛ جرم اتم کربن و هیدروژن یکسان نیست.');
      const host=container.querySelector('.mt-bond-choices');
      host.innerHTML=multiple>1?Array.from({length:n-1},(_,i)=>`<button class="choice-button ${i===state.position?'selected':''}" type="button" data-action="bond" data-index="${i}" aria-pressed="${i===state.position}">${bdi((i+1)+'–'+(i+2))}</button>`).join(''):'<span class="mt-hint">همهٔ پیوندهای کربن–کربن یگانه‌اند.</span>';
    };
    return bind(container,ctx,state,defaults,update,()=>ctx.saveRecord({title:'ساختار '+(result.displayFormula||fml(result.formula)),tool:'molecules',summary:families[state.family]+' با ظرفیت درست برای تمام کربن‌ها',values:[{label:'کربن',value:state.carbons,unit:''},{label:'هیدروژن',value:result.hydrogens,unit:''},{label:'جرم مولی',value:result.molarMass,unit:'g/mol'},{label:'ساختار فعلی',value:structure(state).condensed,unit:''},{label:'ساختار مرجع',value:structure(reference).condensed,unit:''},{label:'مبنای مقایسه',value:state.basis==='mass'?'جرم':'تعداد اتم',unit:''}]}),(key,value,b)=>{
      if(key==='action'&&value==='bond')state.position=Number(b.dataset.index);
      if(key==='action'&&value==='pin'){reference={family:state.family,carbons:state.carbons,position:state.position};ctx.announce('این ساختار برای مقایسه نگه داشته شد.');}
      if(key==='reset')reference={family:'alkane',carbons:3,position:0};
      const min=state.family==='alkane'?1:state.family==='cycloalkane'?3:2;state.carbons=Math.max(min,state.carbons);state.position=Math.min(state.position,Math.max(0,state.carbons-2));container.querySelector('[data-range="carbons"]').min=min;
    });
  }};

  registry.heat={title:'دو نمونه، یک مقدار گرما',chapter:2,pages:'۵۵ تا ۶۱',mount(container,ctx){
    const materials={water:{name:'آب',c:4.184},oil:{name:'روغن زیتون',c:1.97},aluminum:{name:'آلومینیم',c:.9}};
    const defaults={a:'water',b:'oil',massA:200,massB:200,energy:10000,initial:25,mode:'equal',share:50},state={...defaults};
    container.innerHTML=frame('گرماسنج دو نمونه',choices('a','جنس نمونهٔ الف',Object.entries(materials).map(([k,v])=>[k,v.name]))+range('massA','جرم الف',100,500,200,25,'g')+choices('b','جنس نمونهٔ ب',Object.entries(materials).map(([k,v])=>[k,v.name]))+range('massB','جرم ب',100,500,200,25,'g')+choices('mode','نحوهٔ رساندن گرما',[['equal','گرمای برابر به هر نمونه'],['split','تقسیم یک بودجهٔ گرما']])+range('energy','مقدار گرمای انتخابی',0,10000,10000,250,'J')+range('share','سهم الف از بودجهٔ مشترک',0,100,50,5,'%')+`<p class="mt-heat-budget-note mt-hint"></p>`+range('initial','دمای آغاز مشترک',10,40,25,1,'°C'), 'مدل ایده‌آل با گرمای ویژهٔ ثابت، اتلاف صفر و بدون تغییر فاز است. ارتفاع رنگ نمایندهٔ جرم و جنبش ذره‌ها کیفی است. زمان گرم‌شدن یا پخت غذا از این رابطه به دست نمی‌آید.');
    let a,b,qa,qb;
    function vessel(x,r,mat,mass,label){
      const y=265-150*mass/500,bar=Math.min(215,(r.finalTemp/160)*215);
      const fill=`M${x-72},${y} H${x+72} V264 Q${x+72},273 ${x+60},273 H${x-60} Q${x-72},273 ${x-72},264 Z`,solid=mat==='aluminum';
      const speed=Math.max(.8,3.8-r.finalTemp/55),amplitude=solid?2.2:Math.min(9,3+r.finalTemp/30);
      let particles='';for(let i=0;i<15;i++){
        const px=x-54+(i%5)*27,py=y+9+Math.floor(i/5)*(Math.max(16,263-y-18)/2),dx=(i%2?1:-1)*amplitude,dy=((i%3)-1)*amplitude;
        particles+=`<circle cx="${px}" cy="${py}" r="${solid?2.5:3}" class="mt-thermal-particle ${solid?'mt-particle-solid':''}" style="--dx:${dx}px;--dy:${dy}px;--particle-time:${speed.toFixed(2)}s;--particle-delay:${(-i*.23).toFixed(2)}s"/>`;
      }
      let body=`<defs><clipPath id="mt-heat-clip-${x}"><path d="${fill}"/></clipPath></defs><path d="M${x-77},55 V265 Q${x-77},278 ${x-64},278 H${x+64} Q${x+77},278 ${x+77},265 V55" class="mt-vessel"/><path d="${fill}" class="${solid?'mt-solid-fill':'mt-liquid-fill'}"/><g clip-path="url(#mt-heat-clip-${x})">${particles}${solid?'':`<path d="M${x-90},${y+3} Q${x-45},${y-6} ${x},${y+3} T${x+90},${y+3}" class="mt-surface-wave"/>`}</g><line x1="${x+96}" y1="270" x2="${x+96}" y2="55" class="mt-therm-track"/><line x1="${x+96}" y1="270" x2="${x+96}" y2="${270-bar}" class="mt-therm-fill mt-therm-grow" style="transform-origin:${x+96}px 270px;--therm-start:${state.initial/r.finalTemp}"/><circle cx="${x+96}" cy="278" r="11" class="mt-hot-fill"/>`;
      for(let i=0;i<5;i++)body+=line(x+106,270-i*53.75,x+115,270-i*53.75,'mt-tick');
      body+=txt(x,35,label+' · '+materials[mat].name,'mt-svg-title')+txt(x,200,ctx.fa(r.finalTemp,1)+' °C','mt-svg-formula')+txt(x,226,ctx.fa(mass,0)+' g','mt-svg-small')+txt(x,310,'ΔT = '+ctx.fa(r.deltaTemp,1)+' °C','mt-svg-small');return body;
    }
    const update=()=>{
      qa=state.mode==='equal'?state.energy:state.energy*state.share/100;qb=state.mode==='equal'?state.energy:state.energy-qa;
      a=S().heat({mass:state.massA,specificHeat:materials[state.a].c,energy:qa,initialTemp:state.initial});b=S().heat({mass:state.massB,specificHeat:materials[state.b].c,energy:qb,initialTemp:state.initial});
      container.querySelector('.mt-heat-budget-note').textContent=state.mode==='equal'?'در حالت برابر، مقدار انتخابی جداگانه به هر نمونه می‌رسد. تغییر سهم، حالت بودجهٔ مشترک را فعال می‌کند.':'در حالت مشترک، جمع گرمای الف و ب برابر با مقدار انتخابی است؛ گرما میان دو نمونه تقسیم می‌شود.';
      container.querySelector('.mt-scene').innerHTML=svg('دو نمونه و افزایش دمای محاسبه‌شده؛ حرکت ذره‌ها نمایش کیفی دماست.',vessel(155,a,state.a,state.massA,'الف')+vessel(440,b,state.b,state.massB,'ب'),340,'mt-heat-scene');
      const ymax=Math.ceil((state.initial+10000/Math.min(a.heatCapacity,b.heatCapacity))/20)*20,x=q=>65+q/10000*510,y=t=>250-(t-state.initial)/(ymax-state.initial)*200;
      let chart=txt(70,24,'T / °C','mt-svg-small');for(let i=0;i<=4;i++){const t=state.initial+(ymax-state.initial)*i/4;chart+=line(65,y(t),575,y(t),'mt-grid-line')+txt(55,y(t)+5,ctx.fa(t,0),'mt-svg-small','end')+txt(x(i*2500),275,ctx.fa(i*2500,0),'mt-svg-small');}
      chart+=line(65,250,575,250,'mt-axis')+line(65,250,65,45,'mt-axis')+txt(310,305,'گرمای رسیده به هر نمونه / J','mt-svg-small');
      [[a,qa,'a'],[b,qb,'b']].forEach(([r,q,c])=>{const color=c==='a'?'#d4f58b':'#f0e9cf';chart+=`<path d="M65,250 L575,${y(state.initial+10000/r.heatCapacity)}" fill="none" stroke="${color}" stroke-width="3" pathLength="1" class="mt-response-line mt-series-${c} mt-curve-draw"/><path d="M${x(q)},250 V${y(r.finalTemp)} H65" fill="none" stroke="${color}" stroke-width="1" stroke-dasharray="4 5" class="mt-response-guide mt-series-${c}"/><circle cx="${x(q)}" cy="${y(r.finalTemp)}" r="7" fill="#183a43" stroke="${color}" stroke-width="3" class="mt-response-point mt-series-${c}"/>`;});
      const share=qa+qb?qa/(qa+qb)*100:0;
      container.querySelector('.mt-scene-caption').querySelector('strong').textContent=state.mode==='equal'?'گرمای برابر، پاسخ متفاوت':'یک بودجه، دو سهم گرما';
      container.querySelector('.mt-result').innerHTML=`<div class="mt-equation">${bdi('Q = mcΔT  →  ΔT = Q / (mc)')}</div><div class="metric-grid">${metric('ظرفیت گرمایی الف',ctx.fa(a.heatCapacity,1),'J/°C')}${metric('ظرفیت گرمایی ب',ctx.fa(b.heatCapacity,1),'J/°C')}</div>`+analysis('گرما کجا می‌رود؟',legend('الف: '+materials[state.a].name,'ب: '+materials[state.b].name)+`<div class="mt-energy-partition" role="img" aria-label="گرمای الف ${qa} ژول و ب ${qb} ژول"><span style="width:${share}%" class="mt-partition-a"></span><span style="width:${qa+qb?100-share:0}%" class="mt-partition-b"></span></div><div class="mt-two-readings"><span>الف ${bdi(ctx.fa(qa,0)+' J')}</span><span>ب ${bdi(ctx.fa(qb,0)+' J')}</span></div><p class="mt-comparison-conclusion">جمع گرمای ورودی: ${bdi(ctx.fa(qa+qb,0)+' J')}${qa+qb===0?'؛ هر دو نمونه در دمای آغاز می‌مانند.':state.mode==='equal'?'؛ دو سهم برابر.':'؛ سهم‌ها را جابه‌جا کنید و پاسخ دما را ببینید.'}</p>`)+analysis('منحنی پاسخ دما به گرما',svg('دو خط دما بر حسب گرمای ورودی؛ نشانگرها وضعیت فعلی هر نمونه‌اند.',chart,325,'mt-heat-curve'), 'شیب هر خط برابر 1/(mc) است. این نمودار زمان ندارد و انتقال گرما میان دو نمونه را مدل نمی‌کند.')+`<p class="explanation">${Math.abs(a.deltaTemp-b.deltaTemp)<.01?'افزایش دمای دو نمونه در این تنظیم برابر است.':`افزایش دمای نمونهٔ ${a.deltaTemp>b.deltaTemp?'الف':'ب'} بیشتر است؛ هم گرمای دریافتی و هم ظرفیت گرمایی را در مقایسه در نظر بگیرید.`}</p><p class="mt-hint">${bdi('c('+materials[state.a].name+') = '+materials[state.a].c+' J g⁻¹ °C⁻¹')}<br>${bdi('c('+materials[state.b].name+') = '+materials[state.b].c+' J g⁻¹ °C⁻¹')}</p>`;
    };
    return bind(container,ctx,state,defaults,update,()=>ctx.saveRecord({title:'مقایسهٔ '+materials[state.a].name+' و '+materials[state.b].name,tool:'heat',summary:state.mode==='equal'?'گرمای برابر به هر نمونه':'تقسیم یک بودجهٔ گرما',values:[{label:'گرمای الف',value:qa,unit:'J'},{label:'گرمای ب',value:qb,unit:'J'},{label:'دمای نهایی الف',value:Number(a.finalTemp.toFixed(2)),unit:'°C'},{label:'دمای نهایی ب',value:Number(b.finalTemp.toFixed(2)),unit:'°C'}],note:'اتلاف صفر؛ بدون تغییر فاز.'}),(key)=>{if(key==='share')state.mode='split';});
  }};

  const hessReactions=[{eq:'C(s) + O₂(g) → CO₂(g)',h:-393.5,net:{C:-1,O2:-1,CO2:1}},{eq:'H₂(g) + ½O₂(g) → H₂O(l)',h:-286,net:{H2:-1,O2:-.5,H2O:1}},{eq:'CH₄(g) + 2O₂(g) → CO₂(g) + 2H₂O(l)',h:-890,net:{CH4:-1,O2:-2,CO2:1,H2O:2}}];
  const species={C:'C(s)',O2:'O₂(g)',CO2:'CO₂(g)',H2:'H₂(g)',H2O:'H₂O(l)',CH4:'CH₄(g)'};
  const term=(k,v)=>(Math.abs(v)===1?'':Math.abs(v)+' ')+species[k];
  registry.hess={title:'میز قانون هس',chapter:2,pages:'۷۴ تا ۷۷',mount(container,ctx){
    const defaults={f0:1,f1:1,f2:1,cancellation:'before'},state={...defaults};
    container.innerHTML=frame('جمع واکنش‌ها',`<p class="explanation">هدف: ${bdi('C(s) + 2H₂(g) → CH₄(g)')}<br>معادله‌ها را ضرب یا وارونه کنید تا مواد اضافه حذف شوند.</p>`+hessReactions.map((r,i)=>`<div class="mt-reaction-control"><div class="mt-equation mt-small-equation">${bdi(r.eq)}</div><p class="mt-hint">${bdi('ΔH = '+r.h+' kJ')}</p>${range('f'+i,'ضریب واکنش '+ctx.fa(i+1,0),-3,3,1,.5)}<button type="button" class="btn btn-secondary btn-small" data-action="flip" data-index="${i}">وارونه کردن</button></div>`).join('')+`<button type="button" class="btn btn-secondary" data-action="hint">راهنمای یک گام</button><p class="mt-hess-hint" aria-live="polite"></p>`, 'داده‌ها برای ۲۵ درجهٔ سلسیوس‌اند؛ C(s) در این معادله‌ها گرافیت است و آب حالت مایع دارد. قانون هس جمع حسابداری واکنش‌ها در شرایط یکسان است؛ این پله‌ها سازوکار واقعی واکنش نیستند.');
    let result;
    container.querySelector('.mt-controls').insertAdjacentHTML('afterbegin',choices('cancellation','مواد مشترک دو طرف',[['before','پیش از حذف'],['after','پس از حذف']]));
    const update=()=>{
      const factors=[state.f0,state.f1,state.f2];result=S().hess(factors);
      container.querySelectorAll('.mt-reaction-control').forEach((host,i)=>{const entries=Object.entries(hessReactions[i].net).map(([k,v])=>[k,v*factors[i]]),left=entries.filter(([,v])=>v<0).map(([k,v])=>term(k,v)).join(' + ')||'∅',right=entries.filter(([,v])=>v>0).map(([k,v])=>term(k,v)).join(' + ')||'∅';let actual=host.querySelector('.mt-transformed-reaction');if(!actual){host.insertAdjacentHTML('beforeend','<div class="mt-transformed-reaction"></div>');actual=host.querySelector('.mt-transformed-reaction');}actual.innerHTML=`<span>پس از اعمال ضریب:</span><div>${bdi(left+' → '+right)}</div><strong>${bdi('ΔH = '+Number((factors[i]*hessReactions[i].h).toFixed(2))+' kJ')}</strong>`;});
      const totals={};Object.keys(species).forEach(k=>totals[k]={left:0,right:0});hessReactions.forEach((r,i)=>Object.entries(r.net).forEach(([k,v])=>{const n=v*factors[i];totals[k][n<0?'left':'right']+=Math.abs(n);}));
      const levels=[0];factors.forEach((f,i)=>levels.push(levels.at(-1)+f*hessReactions[i].h));const min=Math.min(...levels),max=Math.max(...levels),span=Math.max(200,max-min),y=v=>245-(v-min)/span*190;
      let body=txt(60,30,'ΔH / kJ','mt-svg-small');for(let i=0;i<4;i++){const x=75+i*152;body+=sequence(line(x-30,y(levels[i]),x+50,y(levels[i]),'mt-energy-level')+txt(x+10,y(levels[i])-12,ctx.fa(levels[i],1),'mt-svg-small'),i,'mt-energy-station',190);if(i<3)body+=`<path d="M${x+50},${y(levels[i])} H${x+91} V${y(levels[i+1])} H${x+122}" pathLength="1" class="mt-energy-step mt-hess-path" style="--stagger:${i*190+120}ms"/>`;body+=txt(x+10,285,i===0?'آغاز':'گام '+ctx.fa(i,0),'mt-svg-small');}
      container.querySelector('.mt-scene').innerHTML=svg('مسیر حساب انرژی با سه معادله',body,310,'mt-hess-scene');
      const entries=Object.entries(result.net).filter(([,v])=>Math.abs(v)>1e-8),left=entries.filter(([,v])=>v<0).map(([k,v])=>term(k,v)).join(' + ')||'∅',right=entries.filter(([,v])=>v>0).map(([k,v])=>term(k,v)).join(' + ')||'∅';
      container.querySelector('.mt-result').innerHTML=`<div class="mt-equation">${bdi(left+' → '+right)}</div><div class="metric-grid">${metric('جمع آنتالپی',ctx.fa(result.deltaH,1),'kJ')}${metric('وضعیت هدف',result.isTarget?'رسیدیم':'هنوز نه')}</div><div class="mt-table-wrap"><table class="mt-table"><caption>مواد مشترک از دو طرف حذف می‌شوند</caption><thead><tr><th>گونه</th><th>سمت چپ</th><th>سمت راست</th><th>حذف‌شده</th></tr></thead><tbody>${Object.entries(totals).filter(([,v])=>v.left+v.right>0).map(([k,v])=>`<tr><th>${bdi(species[k])}</th><td>${ctx.fa(v.left,2)}</td><td>${ctx.fa(v.right,2)}</td><td>${ctx.fa(Math.min(v.left,v.right),2)}</td></tr>`).join('')}</tbody></table></div><p class="mt-proof">${result.isTarget?'معادلهٔ هدف ساخته شد: ΔH برابر با منفی ۷۵٫۵ کیلوژول است.':'برای رسیدن به هدف، گرافیت و هیدروژن در چپ و متان در راست باقی بمانند.'}</p>`;
      const maximum=Math.max(1,...Object.values(totals).flatMap(v=>[v.left,v.right])),after=state.cancellation==='after';
      const rows=Object.entries(totals).filter(([,v])=>v.left+v.right>0).map(([k,v])=>{const common=Math.min(v.left,v.right),l=after?v.left-common:v.left,r=after?v.right-common:v.right;return `<div class="mt-cancel-row"><div class="mt-cancel-species">${bdi(species[k])}<small>${common?'حذف از هر طرف: '+ctx.fa(common,2):'بدون مادهٔ مشترک'}</small></div><div class="mt-cancel-pair"><div class="mt-cancel-side"><span>چپ ${ctx.fa(l,2)}</span><div class="mt-cancel-track"><i style="width:${l/maximum*100}%" class="mt-cancel-left"></i>${!after&&common?`<s style="width:${common/maximum*100}%" aria-label="بخش قابل حذف"></s>`:''}</div></div><div class="mt-cancel-side"><span>راست ${ctx.fa(r,2)}</span><div class="mt-cancel-track"><i style="width:${r/maximum*100}%" class="mt-cancel-right"></i>${!after&&common?`<s style="width:${common/maximum*100}%" aria-label="بخش قابل حذف"></s>`:''}</div></div></div></div>`;}).join('');
      container.querySelector('.mt-result').insertAdjacentHTML('afterbegin',analysis(after?'آنچه پس از حذف باقی می‌ماند':'مواد را در دو طرف روی هم بگذار',rows||'<p class="explanation">همهٔ ضرایب صفرند؛ واکنشی وارد جمع نشده است.</p>', 'طول نوارها متناسب با ضرایب مولی است. خط‌خوردگی، مقدار مشترک قابل حذف از هر دو طرف را نشان می‌دهد؛ حذف گونه‌ها، جمع آنتالپی را تغییر نمی‌دهد.'));
    };
    return bind(container,ctx,state,defaults,update,()=>ctx.saveRecord({title:'جمع واکنش‌ها با قانون هس',tool:'hess',summary:result.isTarget?'ساخت موفق معادلهٔ تولید متان':'جمع فعلی معادله‌ها',values:[{label:'ضرایب سه واکنش',value:[state.f0,state.f1,state.f2].join('، '),unit:''},{label:'آنتالپی مجموع',value:result.deltaH,unit:'kJ'}]}),(key,value,b)=>{
      if(key==='action'&&value==='flip')state['f'+b.dataset.index]*=-1;
      if(key==='action'&&value==='hint')container.querySelector('.mt-hess-hint').textContent=state.f2!==-1?'متان باید در سمت فراورده باشد؛ واکنش سوم را با ضریب منفی یک وارد کنید.':state.f1!==2?'برای حذف دو مول آب، واکنش دوم را دو برابر کنید.':state.f0!==1?'یک مول گرافیت لازم است؛ ضریب واکنش نخست را یک بگذارید.':'هر سه ضریب درست‌اند؛ حذف اکسیژن، آب و کربن‌دی‌اکسید را در جدول ببینید.';
      else container.querySelector('.mt-hess-hint').textContent='';
    });
  }};

  const rateRows=[{t:0,m:65.98},{t:10,m:65.32},{t:20,m:64.88},{t:30,m:64.66},{t:40,m:64.55},{t:50,m:64.5},{t:60,m:64.5}];
  registry.rates={title:'از داده تا سرعت واکنش',chapter:2,pages:'۸۷ تا ۹۰',mount(container,ctx){
    const defaults={start:0,end:2,refStart:3,refEnd:5,quantity:'moles'},state={...defaults};
    container.innerHTML=frame('سرعت متوسط واکنش',`<div class="mt-equation">${bdi('CaCO₃ + 2HCl → CaCl₂ + CO₂ + H₂O')}</div>`+choices('quantity','کمیت نمودار',[['moles','مول CO₂ تولیدشده'],['mass','جرم مخلوط باقی‌مانده']])+range('start','نقطهٔ آغاز بازه',0,5,0)+range('end','نقطهٔ پایان بازه',1,6,2)+`<p class="mt-interval-readout"></p><p class="explanation">دو نقطهٔ اندازه‌گیری‌شده را انتخاب کنید. شیب خط واصل، سرعت متوسط در همان بازه است.</p>`, 'داده‌های جدول صفحهٔ ۸۷ کتاب؛ اندازه‌گیری هر ۱۰ ثانیه. خط میان نقطه‌ها فقط راهنمای خواندن است. از این داده‌ها قانون سرعت یا سرعت لحظه‌ای نتیجه نمی‌گیریم. رقم‌های اعشار حاصل محاسبه‌اند؛ دقت اندازه‌گیری را بیشتر نمی‌کنند.');
    container.querySelector('.mt-controls').insertAdjacentHTML('afterbegin',range('refStart','آغاز بازهٔ مقایسه (ب)',0,5,3)+range('refEnd','پایان بازهٔ مقایسه (ب)',1,6,5));
    let result,points,reference;
    const update=()=>{
      points=rateRows.map(r=>({t:r.t,value:state.quantity==='mass'?r.m:Number(((65.98-r.m)/44).toFixed(10))}));const p=points[state.start],q=points[state.end];result=S().rateBetween(points,p.t,q.t);
      const rp=points[state.refStart],rq=points[state.refEnd];reference=S().rateBetween(points,rp.t,rq.t);
      const mass=state.quantity==='mass',low=mass?64.4:0,high=mass?66.1:.038,x=t=>65+t/60*510,y=v=>255-(v-low)/(high-low)*205;
      let body=`<rect x="${x(p.t)}" y="40" width="${x(q.t)-x(p.t)}" height="215" class="mt-interval-band" style="transform-origin:${x(p.t)}px 255px"/>`;for(let i=0;i<5;i++){const value=low+(high-low)*i/4,yy=y(value);body+=line(65,yy,575,yy,'mt-grid-line')+txt(52,yy+4,ctx.fa(value,mass?1:3),'mt-svg-small','end');}
      for(let i=0;i<7;i++)body+=txt(x(i*10),280,ctx.fa(i*10,0),'mt-svg-small');body+=line(65,255,580,255,'mt-axis')+line(65,255,65,40,'mt-axis');
      body+=`<polyline points="${points.map(p=>x(p.t)+','+y(p.value)).join(' ')}" pathLength="1" class="mt-data-line mt-curve-draw"/>`;
      body+=`<path d="M${x(rp.t)},${y(rp.value)} L${x(rq.t)},${y(rq.value)}" class="mt-reference-secant"/><circle cx="${x(rp.t)}" cy="${y(rp.value)}" r="10" class="mt-reference-point"/><circle cx="${x(rq.t)}" cy="${y(rq.value)}" r="10" class="mt-reference-point"/>`;
      body+=`<path d="M${x(p.t)},${y(p.value)} H${x(q.t)} V${y(q.value)}" class="mt-secant-guide"/>`+line(x(p.t),y(p.value),x(q.t),y(q.value),'mt-secant');
      points.forEach((p,i)=>{body+=sequence(`<circle cx="${x(p.t)}" cy="${y(p.value)}" r="${i===state.start||i===state.end?7:4}" class="${i===state.start||i===state.end?'mt-selected-point':'mt-data-point'}"/>`,i,'mt-data-reveal',65);});
      body+=txt(310,308,'زمان (ثانیه)','mt-svg-small')+txt(310,22,mass?'جرم مخلوط / g':'مقدار CO₂ / mol','mt-svg-small');
      container.querySelector('.mt-scene').innerHTML=legend('الف: بازهٔ اصلی، خط پیوسته','ب: بازهٔ مقایسه، خط چین')+svg('نقاط واقعی کتاب و دو خط قاطع برای مقایسهٔ سرعت متوسط',body,330,'mt-rates-scene');
      ['refStart','refEnd'].forEach(key=>{const t=rateRows[state[key]].t;container.querySelector(`[data-output="${key}"]`).textContent=ctx.fa(t,0)+' ثانیه';container.querySelector(`[data-range="${key}"]`).setAttribute('aria-valuetext',ctx.fa(t,0)+' ثانیه');});
      container.querySelector('[data-output="start"]').textContent=ctx.fa(p.t,0)+' ثانیه';container.querySelector('[data-output="end"]').textContent=ctx.fa(q.t,0)+' ثانیه';container.querySelector('.mt-interval-readout').textContent='بازهٔ '+ctx.fa(p.t,0)+' تا '+ctx.fa(q.t,0)+' ثانیه';
      container.querySelector('[data-range="start"]').setAttribute('aria-valuetext',ctx.fa(p.t,0)+' ثانیه');container.querySelector('[data-range="end"]').setAttribute('aria-valuetext',ctx.fa(q.t,0)+' ثانیه');
      container.querySelector('.mt-result').innerHTML=`<div class="metric-grid">${metric('تغییر مقدار',ctx.fa(result.delta,mass?2:4),mass?'g':'mol')}${metric(mass?'آهنگ کاهش جرم':'سرعت متوسط تولید CO₂',ctx.fa(mass?-result.rate:result.rate,mass?4:6),mass?'g/s':'mol/s')}</div><p class="explanation">${p.t>=50?'از ثانیهٔ ۵۰ جرم ثابت است؛ در دادهٔ کتاب واکنش پایان یافته و سرعت این بازه صفر است.':mass?'کاهش جرم از خروج گاز CO₂ است. برای تبدیل آهنگ کاهش جرم به مول بر ثانیه، بر ۴۴ تقسیم کنید.':'با پیشرفت واکنش، مقدار CO₂ بیشتر می‌شود؛ شیب بازه‌های پایانی کوچک‌تر است.'}</p><div class="mt-table-wrap"><table class="mt-table"><caption>دادهٔ آزمایش و محاسبهٔ مقدار CO₂</caption><thead><tr><th>زمان (s)</th><th>جرم مخلوط (g)</th><th>CO₂ (mol)</th></tr></thead><tbody>${rateRows.map((r,i)=>`<tr class="${i>=state.start&&i<=state.end?'mt-row-active':''}"><td>${ctx.fa(r.t,0)}</td><td>${ctx.fa(r.m,2)}</td><td>${ctx.fa((65.98-r.m)/44,4)}</td></tr>`).join('')}</tbody></table></div>`;
      const av=Math.abs(result.rate),bv=Math.abs(reference.rate),maxRate=Math.max(av,bv,1e-10),unit=mass?'g/s':'mol/s';
      const rateBar=(value,label,cls)=>`<div class="mt-rate-comparison"><div><strong>${label}</strong><span>${bdi(ctx.fa(value,mass?4:6)+' '+unit)}</span></div><div class="mt-comparison-track"><i class="${cls}" style="width:${value/maxRate*100}%"></i></div></div>`;
      container.querySelector('.mt-result').insertAdjacentHTML('afterbegin',analysis('دو بازه، دو سرعت متوسط',rateBar(av,'الف: '+ctx.fa(p.t,0)+' تا '+ctx.fa(q.t,0)+' ثانیه','mt-rate-a')+rateBar(bv,'ب: '+ctx.fa(rp.t,0)+' تا '+ctx.fa(rq.t,0)+' ثانیه','mt-rate-b')+`<p class="mt-comparison-conclusion">${av===0&&bv===0?'هر دو بازه روی بخش ثابت داده‌اند؛ هر دو سرعت صفر است.':bv===0?'سرعت بازهٔ ب صفر است؛ نسبت عددی الف به ب تعریف نمی‌شود.':'سرعت الف تقریباً '+ctx.fa(av/bv,2)+' برابر سرعت ب است.'}</p>`, 'این مقایسه از همان هفت اندازه‌گیری به دست می‌آید. طول نوارها آهنگ تولید گاز یا کاهش جرم را نشان می‌دهد، نه سرعت لحظه‌ای.'));
    };
    return bind(container,ctx,state,defaults,update,()=>ctx.saveRecord({title:'سرعت متوسط در بازهٔ '+rateRows[state.start].t+' تا '+rateRows[state.end].t+' ثانیه',tool:'rates',summary:state.quantity==='mass'?'آهنگ کاهش جرم بر اثر خروج گاز':'سرعت متوسط تولید CO₂',values:[{label:'زمان آغاز',value:rateRows[state.start].t,unit:'s'},{label:'زمان پایان',value:rateRows[state.end].t,unit:'s'},{label:'سرعت متوسط',value:Number(Math.abs(result.rate).toPrecision(4)),unit:state.quantity==='mass'?'g/s':'mol/s'},{label:'بازهٔ مقایسه',value:rateRows[state.refStart].t+'–'+rateRows[state.refEnd].t,unit:'s'},{label:'سرعت مقایسه',value:Number(Math.abs(reference.rate).toPrecision(4)),unit:state.quantity==='mass'?'g/s':'mol/s'}],note:'بر پایهٔ داده‌های کتاب؛ میان‌یابی نشده است.'}),(key)=>{if(state.start>=state.end){if(key==='start')state.end=state.start+1;else state.start=state.end-1;}if(state.refStart>=state.refEnd){if(key==='refStart')state.refEnd=state.refStart+1;else state.refStart=state.refEnd-1;}});
  }};

  const monomers={ethene:{name:'اتن',poly:'پلی‌اتن',formula:'CH₂=CH₂',unit:'CH₂–CH₂',side:'H',use:'کیسه و ظرف‌های پلی‌اتنی'},propene:{name:'پروپن',poly:'پلی‌پروپن',formula:'CH₂=CH(CH₃)',unit:'CH₂–CH(CH₃)',side:'CH₃',use:'بدنهٔ سرنگ'},vinyl:{name:'وینیل کلرید',poly:'پلی‌وینیل کلرید',formula:'CH₂=CHCl',unit:'CH₂–CHCl',side:'Cl',use:'کیسهٔ خون'},styrene:{name:'استیرن',poly:'پلی‌استیرن',formula:'CH₂=CH(C₆H₅)',unit:'CH₂–CH(C₆H₅)',side:'C₆H₅',use:'ظرف‌های پلی‌استیرنی'},cyano:{name:'سیانواتن',poly:'پلی‌سیانواتن',formula:'CH₂=CHCN',unit:'CH₂–CHCN',side:'CN',use:'الیاف پتو'},tetra:{name:'تترافلوئورواتن',poly:'تفلون',formula:'CF₂=CF₂',unit:'CF₂–CF₂',side:'F',use:'نخ دندان'}};
  registry.polymers={title:'از مونومر تا زنجیر',chapter:3,pages:'۱۰۴ تا ۱۰۹',mount(container,ctx){
    const defaults={monomer:'ethene',units:4,joined:false,packing:'linear',contacts:true},state={...defaults};
    container.innerHTML=frame('ساخت زنجیر بسپار',choices('monomer','مونومر',Object.entries(monomers).map(([k,v])=>[k,v.name]))+range('units','واحدهای نمایشی',2,6,4)+`<button type="button" class="btn btn-primary mt-join" data-action="join">اتصال مونومرها</button>`+choices('packing','آرایش پلی‌اتن برای مقایسه',[['linear','بدون شاخه'],['branched','شاخه‌دار']]), 'تعداد واحدها یک قطعهٔ نمایشی است، نه طول واقعی پلیمر. زنجیر از دو سو ادامه دارد. آرایش شاخه‌ها کیفی است و نرخ واکنش یا چگالیِ پیوسته پیش‌بینی نمی‌شود.');
    container.querySelector('.mt-controls').insertAdjacentHTML('afterbegin','<button type="button" class="btn btn-secondary mt-contacts-toggle" data-action="contacts">پنهان‌کردن تماس زنجیرها</button>');
    const update=()=>{
      const m=monomers[state.monomer],n=state.units,columns=Math.min(3,n),step=540/columns,rows=Math.ceil(n/columns),firstLabel=m.side==='F'?'CF₂':'CH₂',secondLabel=m.side==='F'?'CF₂':m.side==='H'?'CH₂':'CH',firstPad=24,secondPad=secondLabel==='CH'?19:24;
      const positions=Array.from({length:n},(_,i)=>{const row=Math.floor(i/columns),reverse=state.joined&&row%2===1,col=reverse?columns-1-i%columns:i%columns,base=40+col*step;return {x:base+step*(reverse?.62:.22),b:base+step*(reverse?.22:.62),y:85+row*145,direction:reverse?-1:1};});
      let body=txt(310,27,state.joined?'قطعهٔ زنجیر '+m.poly:'مونومرهای '+m.name,'mt-svg-title');
      for(let i=0;i<n;i++){
        const {x,b,y:mid,direction}=positions[i],from=x+direction*firstPad,to=b-direction*secondPad;
        let unit=line(from,state.joined?mid:mid-3,to,state.joined?mid:mid-3,'mt-bond mt-poly-internal');if(!state.joined)unit+=line(from,mid+3,to,mid+3,'mt-bond mt-poly-internal');
        unit+=txt(x,mid+6,firstLabel,'mt-poly-atom')+txt(b,mid+6,secondLabel,'mt-poly-atom');
        if(m.side!=='H'&&m.side!=='F')unit+=line(b,mid+15,b,mid+34,'mt-bond')+txt(b,mid+58,m.side,'mt-hydrogen');
        body+=`<g class="${state.joined?'mt-poly-connect':'mt-poly-unit'}" style="--stagger:${i*80}ms;--unit-shift:${(i-(n-1)/2)*10}px">${unit}</g>`;
        if(state.joined&&i<n-1){const next=positions[i+1],start=b+direction*secondPad,end=next.x-next.direction*firstPad;body+=sequence(mid===next.y?line(start,mid,end,next.y,'mt-new-bond mt-draw'):`<path d="M${start},${mid} H584 V${next.y} H${end}" fill="none" pathLength="1" class="mt-new-bond mt-draw mt-poly-row-link"/>`,i,'mt-poly-new-link',90);}
      }
      if(state.joined){const first=positions[0],last=positions.at(-1),end=last.b+last.direction*secondPad;body+=line(first.x-firstPad-25,first.y,first.x-firstPad,first.y,'mt-bond')+txt(first.x-firstPad-36,first.y+6,'…','mt-svg-small')+line(end,last.y,end+last.direction*25,last.y,'mt-bond')+txt(end+last.direction*36,last.y+6,'…','mt-svg-small');}
      body+=txt(310,rows*145+57,state.joined?'[ '+m.unit+' ]ₙ':m.formula,'mt-svg-formula');
      container.querySelector('.mt-scene').innerHTML=svg('نمای ساختاری مونومرها و تغییر پیوند دوگانه به پیوند یگانه در زنجیر',body,rows*145+82,state.joined?'mt-polymer-scene mt-connected':'mt-polymer-scene');
      function packingDiagram(branched){let drawing='';for(let row=0;row<4;row++){const y=35+row*(branched?40:25),pts=Array.from({length:11},(_,i)=>[38+i*54,y+(i%2)*12]);let chain=`<polyline points="${pts.map(p=>p.join(',')).join(' ')}" pathLength="1" class="mt-chain mt-packing-draw"/>`;if(branched)for(let i=2;i<10;i+=4){const p=pts[i];chain+=`<path d="M${p[0]},${p[1]} l18,-22 l22,12 l12,-18" pathLength="1" class="mt-chain-branch mt-packing-draw"/>`;}if(state.contacts&&row<3)for(let j=branched?1:0;j<10;j+=branched?4:2)chain+=line(pts[j][0],pts[j][1]+4,pts[j][0],pts[j][1]+(branched?36:21),'mt-interchain-contact');drawing+=sequence(chain,row,'mt-packing-row',70);}return svg(branched?'شاخه‌ها مانع کنارهم‌چینی نزدیک زنجیرها هستند':'زنجیرهای بدون شاخه با تماس نزدیک‌تر کنار هم قرار می‌گیرند',drawing,205,'mt-packing-comparison');}
      const packingCard=(kind,name,density,description)=>`<section class="mt-packing-sample ${state.packing===kind?'mt-sample-selected':''}"><h4>${name}${state.packing===kind?'<span>در حال بررسی</span>':''}</h4>${packingDiagram(kind==='branched')}<div class="mt-density-reading">${bdi(density+' g/cm³')}<small>چگالی نمونهٔ کتاب</small></div><p>${description}</p></section>`;
      container.querySelector('.mt-result').innerHTML=`<p class="mt-proof">${state.joined?'پیوند دوگانهٔ هر مونومر به یگانه تبدیل شد و پیوندهای تازهٔ بین واحدها زنجیر را ادامه دادند.':'پیش از اتصال، پیوند دوگانهٔ هر مونومر را پیدا کنید.'}</p><div class="mt-equation">${bdi('n '+m.formula+' → [–'+m.unit+'–]ₙ')}</div><div class="mt-poly-account"><span><strong>${ctx.fa(n,0)}</strong> واحد نمایشی</span><span><strong>${ctx.fa(n*2,0)}</strong> کربن در ستون زنجیر</span><span><strong>${ctx.fa(state.joined?n-1:0,0)}</strong> اتصال تازه بین واحدهای این قطعه</span></div><p class="explanation">کاربرد مطرح‌شده در کتاب: ${m.use}.</p>`+analysis('چرا شاخه‌دار بودن اهمیت دارد؟',`<div class="mt-packing-pair">${packingCard('linear','پلی‌اتن بدون شاخه','0.97','قرارگیری نزدیک‌تر؛ برهم‌کنش میان زنجیرها بیشتر و نمونهٔ سنگین‌تر.')}${packingCard('branched','پلی‌اتن شاخه‌دار','0.92','قرارگیری نزدیک دشوارتر؛ برهم‌کنش میان زنجیرها کمتر و نمونهٔ سبک‌تر.')}</div>`, 'این مقایسه فقط برای دو نمونهٔ پلی‌اتن صفحهٔ ۱۰۹ است و با تغییر مونومر بالا عوض نمی‌شود. خط‌چین‌های بین زنجیرها نمایش کیفی تماس‌اند، نه پیوند کووالانسی یا شمارش واقعی نیروها. فاصله‌ها مقیاس واقعی ندارند.');
      container.querySelector('.mt-contacts-toggle').textContent=state.contacts?'پنهان‌کردن تماس زنجیرها':'نمایش تماس زنجیرها';container.querySelector('.mt-contacts-toggle').setAttribute('aria-pressed',String(state.contacts));
      container.querySelector('.mt-join').textContent=state.joined?'بازگشت به نمای مونومرها':'اتصال مونومرها';container.querySelector('.mt-join').setAttribute('aria-pressed',String(state.joined));
    };
    return bind(container,ctx,state,defaults,update,()=>ctx.saveRecord({title:monomers[state.monomer].poly,tool:'polymers',summary:state.joined?'اتصال افزایشی مونومرها و حفظ گروه جانبی':'ساختار مونومر پیش از اتصال',values:[{label:'مونومر',value:monomers[state.monomer].formula,unit:''},{label:'واحدهای نمایشی',value:state.units,unit:''},{label:'واحد تکرارشونده',value:monomers[state.monomer].unit,unit:''},{label:'آرایش مقایسه‌ای پلی‌اتن',value:state.packing==='linear'?'بدون شاخه':'شاخه‌دار',unit:''}]}),(key,value)=>{if(key==='action'&&value==='join')state.joined=!state.joined;if(key==='action'&&value==='contacts')state.contacts=!state.contacts;if(key==='monomer')state.joined=false;});
  }};

  const fractions=[{name:'گاز پالایشگاهی',use:'سوخت گازی',desc:'سبک‌ترین و فرّارترین بخش‌ها به بالای برج می‌رسند؛ این خروجی گازی است.'},{name:'بنزین',use:'سوخت خودرو',desc:'برشی از هیدروکربن‌های نسبتاً سبک که در بخش بالایی جدا می‌شود.'},{name:'نفتا',use:'خوراک صنایع پتروشیمی',desc:'یک برش نفتی و مخلوطی از هیدروکربن‌هاست؛ یک مادهٔ خالص نیست.'},{name:'نفت سفید',use:'سوخت و پایهٔ سوخت هواپیما',desc:'در مقایسه با برش‌های بالاتر، مولکول‌های بزرگ‌تر و فرّاریت کمتری دارد.'},{name:'گازوئیل',use:'سوخت موتور دیزل',desc:'در ناحیه‌ای گرم‌تر از نفت سفید از برج خارج می‌شود.'},{name:'نفت کوره',use:'سوخت صنعتی',desc:'برشی سنگین‌تر است و در بخش گرم‌تر و پایین‌تر برج جدا می‌شود.'},{name:'روان‌کننده‌ها',use:'روان‌کاری',desc:'اجزای سنگین و کم‌فرّار در ناحیهٔ پایین برج جمع می‌شوند.'},{name:'آسفالت',use:'راه‌سازی',desc:'سنگین‌ترین باقیمانده در پایین برج می‌ماند؛ مانند برش‌های بالایی بالا نمی‌رود.'}];
  registry.refinery={title:'مسیر یک برش در برج تقطیر',chapter:1,pages:'۴۴ تا ۴۵',mount(container,ctx){
    const defaults={fraction:'3',zone:3,flow:true,reference:'1',property:'boiling'},state={...defaults};
    container.innerHTML=frame('برج تقطیر نفت خام',choices('fraction','برش نفتی',fractions.map((f,i)=>[String(i),f.name]))+range('zone','ناحیهٔ برج؛ از بالا به پایین',0,7,3)+`<button type="button" class="btn btn-primary mt-flow" data-action="flow">مسیر این برش را ببین</button><p class="mt-zone-feedback" aria-live="polite"></p>`, 'برج یک مدل کیفی از شکل صفحهٔ ۴۵ است؛ هر خروجی یک مخلوط است. دمای سینی، درصد محصول یا بازده عددی پیش‌بینی نمی‌شود. تقطیر مولکول‌ها را تغییر نمی‌دهد.');
    container.querySelector('.mt-controls').insertAdjacentHTML('afterbegin',choices('reference','برش مرجع برای مقایسه',fractions.map((f,i)=>[String(i),f.name]))+choices('property','ردگیری ویژگی',[['boiling','بازهٔ جوش'],['size','اندازهٔ مولکول'],['volatility','فرّاریت']]));
    const update=()=>{
      const index=Number(state.fraction),fraction=fractions[index],zone=state.zone,reference=Number(state.reference);
      let body=`<path d="M246,48 Q246,20 282,20 H304 Q340,20 340,48 V350 Q340,372 316,372 H270 Q246,372 246,350Z" class="mt-tower"/>`;
      for(let i=0;i<8;i++){
        const y=55+i*40;body+=`<rect x="251" y="${y-14}" width="84" height="30" rx="3" class="mt-zone ${i===zone?'mt-zone-active':''}"/>`+line(260,y+14,328,y+14,'mt-tray')+`<path d="M340,${y} H${i%2?445:395} V${y+9}" class="mt-pipe ${i===index?'mt-pipe-active':''}"/>`+txt(i%2?465:410,y+5,fractions[i].name,'mt-svg-small','start');
      }
      body+=`<path d="M80,310 H155 V335 H245" class="mt-feed"/><rect x="42" y="270" width="72" height="80" rx="12" class="mt-crude"/>`+txt(78,302,'نفت','mt-svg-title')+txt(78,324,'خام','mt-svg-title')+txt(170,375,'گرم‌کردن','mt-svg-small');
      body+=line(205,75,205,270,'mt-temp-axis')+txt(184,60,'خنک‌تر','mt-svg-small')+txt(184,292,'گرم‌تر','mt-svg-small');
      body+=`<path d="M246,${55+reference*40} H222" class="mt-reference-secant"/><circle cx="222" cy="${55+reference*40}" r="7" class="mt-reference-point"/>`;
      if(state.flow){const y=55+index*40;body+=`<path d="M115,310 H154 V335 H292 V${y} H${index%2?445:395}" class="mt-fraction-route mt-flow-running"/>`;if(index<7)for(let i=0;i<4;i++)body+=`<circle cx="292" cy="335" r="4" class="mt-route-dot mt-vapor-trace" style="--rise:${335-y}px;--flow-delay:${-i*.8}s"/>`;}
      container.querySelector('.mt-scene').innerHTML=legend('برش انتخابی: '+fraction.name,'مرجع: '+fractions[reference].name)+svg('برج تقطیر با هشت خروجی و کاهش دما رو به بالا',body,405,'mt-refinery-scene');
      container.querySelector('.mt-result').innerHTML=`<div class="mt-fraction-detail"><h3>${fraction.name}</h3><p>${fraction.desc}</p><p class="mt-hint">کاربرد: ${fraction.use}</p></div><p class="explanation">هرچه به بالای برج برویم، دما پایین‌تر است. اجزای کم‌فرّار زودتر مایع می‌شوند و اجزای فرّارتر بالاتر می‌روند.</p>`;
      const properties={boiling:{title:'بازهٔ جوش',up:'پایین‌تر',down:'بالاتر',description:'اجزای کم‌فرّار در بخش گرم‌تر جدا می‌شوند؛ هر برش بازهٔ جوش دارد، نه یک نقطهٔ جوش ثابت.'},size:{title:'اندازهٔ مولکول',up:'عموماً کوچک‌تر',down:'عموماً بزرگ‌تر',description:'رو به پایین برج، هیدروکربن‌های سنگین‌تر و عموماً بزرگ‌تر دیده می‌شوند. شمار دقیق کربن برای این برش‌ها در مدل تعیین نشده است.'},volatility:{title:'فرّاریت',up:'بیشتر',down:'کمتر',description:'اجزای فرّارتر بیشتر در حالت بخار بالا می‌روند. برش پایین برج باقیماندهٔ کم‌فرّار است.'}},prop=properties[state.property];
      const levels=['بالای برج','میانهٔ برج','پایین برج'],band=i=>i<=2?0:i<=4?1:2;
      const row=(i,label,cls)=>`<div class="mt-fraction-comparison"><strong>${label}: ${fractions[i].name}</strong><div class="mt-fraction-zones">${levels.map((name,k)=>`<span class="${band(i)===k?cls:''}">${name}${band(i)===k?'<b>●</b>':''}</span>`).join('')}</div></div>`;
      const comparison=index===reference?'هر دو انتخاب یک برش‌اند.':`${fraction.name} در شکل کتاب ${index<reference?'بالاتر':'پایین‌تر'} از ${fractions[reference].name} است؛ در روند کلی، ${prop.title} آن ${index<reference?prop.up:prop.down} است.`;
      container.querySelector('.mt-result').innerHTML+=analysis('از جای برش تا '+prop.title,`<div class="mt-property-direction"><span>بالای برج<br><strong>${prop.up}</strong></span><span class="mt-direction-arrow" aria-hidden="true">↓</span><span>پایین برج<br><strong>${prop.down}</strong></span></div>${row(index,'انتخاب','mt-zone-choice-a')}${row(reference,'مرجع','mt-zone-choice-b')}<p class="mt-comparison-conclusion">${comparison}</p>`, prop.description+' جای‌گذاری در سه ناحیه فقط ترتیب کیفی شکل کتاب را خلاصه می‌کند؛ فاصلهٔ علامت‌ها اختلاف عددی خواص نیست و ترکیب برش‌ها می‌تواند هم‌پوشانی داشته باشد.');
      const feedback=container.querySelector('.mt-zone-feedback');feedback.textContent=zone===index?'ناحیهٔ انتخابی با جای این برش در شکل کتاب سازگار است.':`جای ${fraction.name} در شکل کتاب ${index<zone?'بالاتر و خنک‌تر':'پایین‌تر و گرم‌تر'} از ناحیهٔ انتخابی است.`;
      container.querySelector('[data-output="zone"]').textContent='ناحیهٔ '+ctx.fa(zone+1,0);container.querySelector('.mt-flow').textContent=state.flow?'پنهان‌کردن مسیر':'مسیر این برش را ببین';container.querySelector('.mt-flow').setAttribute('aria-pressed',String(state.flow));
    };
    return bind(container,ctx,state,defaults,update,()=>ctx.saveRecord({title:'برش '+fractions[Number(state.fraction)].name,tool:'refinery',summary:'جداسازی بر پایهٔ تفاوت فرّاریت؛ بدون تغییر شیمیایی',values:[{label:'جای برش از بالای برج',value:Number(state.fraction)+1,unit:''},{label:'کاربرد',value:fractions[Number(state.fraction)].use,unit:''}],note:'مدل کیفی؛ دما و بازده عددی تعیین نشده‌اند.'}),(key,value)=>{if(key==='action'&&value==='flow')state.flow=!state.flow;});
  }};

  const elementRows=[
    ['H','هیدروژن',1,1,'nonmetal','1s¹',[1]],['He','هلیم',18,1,'nonmetal','1s²',[2]],['Li','لیتیم',1,2,'metal','[He] 2s¹',[2,1]],['Be','بریلیم',2,2,'metal','[He] 2s²',[2,2]],['B','بور',13,2,'metalloid','[He] 2s² 2p¹',[2,3]],['C','کربن',14,2,'nonmetal','[He] 2s² 2p²',[2,4]],['N','نیتروژن',15,2,'nonmetal','[He] 2s² 2p³',[2,5]],['O','اکسیژن',16,2,'nonmetal','[He] 2s² 2p⁴',[2,6]],['F','فلوئور',17,2,'nonmetal','[He] 2s² 2p⁵',[2,7]],['Ne','نئون',18,2,'nonmetal','[He] 2s² 2p⁶',[2,8]],
    ['Na','سدیم',1,3,'metal','[Ne] 3s¹',[2,8,1]],['Mg','منیزیم',2,3,'metal','[Ne] 3s²',[2,8,2]],['Al','آلومینیم',13,3,'metal','[Ne] 3s² 3p¹',[2,8,3]],['Si','سیلیسیم',14,3,'metalloid','[Ne] 3s² 3p²',[2,8,4]],['P','فسفر',15,3,'nonmetal','[Ne] 3s² 3p³',[2,8,5]],['S','گوگرد',16,3,'nonmetal','[Ne] 3s² 3p⁴',[2,8,6]],['Cl','کلر',17,3,'nonmetal','[Ne] 3s² 3p⁵',[2,8,7]],['Ar','آرگون',18,3,'nonmetal','[Ne] 3s² 3p⁶',[2,8,8]],
    ['K','پتاسیم',1,4,'metal','[Ar] 4s¹',[2,8,8,1]],['Ca','کلسیم',2,4,'metal','[Ar] 4s²',[2,8,8,2]],['Sc','اسکاندیم',3,4,'metal','[Ar] 3d¹ 4s²',[2,8,9,2]],['Ti','تیتانیم',4,4,'metal','[Ar] 3d² 4s²',[2,8,10,2]],['V','وانادیم',5,4,'metal','[Ar] 3d³ 4s²',[2,8,11,2]],['Cr','کروم',6,4,'metal','[Ar] 3d⁵ 4s¹',[2,8,13,1]],['Mn','منگنز',7,4,'metal','[Ar] 3d⁵ 4s²',[2,8,13,2]],['Fe','آهن',8,4,'metal','[Ar] 3d⁶ 4s²',[2,8,14,2]],['Co','کبالت',9,4,'metal','[Ar] 3d⁷ 4s²',[2,8,15,2]],['Ni','نیکل',10,4,'metal','[Ar] 3d⁸ 4s²',[2,8,16,2]],['Cu','مس',11,4,'metal','[Ar] 3d¹⁰ 4s¹',[2,8,18,1]],['Zn','روی',12,4,'metal','[Ar] 3d¹⁰ 4s²',[2,8,18,2]],['Ga','گالیم',13,4,'metal','[Ar] 3d¹⁰ 4s² 4p¹',[2,8,18,3]],['Ge','ژرمانیم',14,4,'metalloid','[Ar] 3d¹⁰ 4s² 4p²',[2,8,18,4]],['As','آرسنیک',15,4,'metalloid','[Ar] 3d¹⁰ 4s² 4p³',[2,8,18,5]],['Se','سلنیم',16,4,'nonmetal','[Ar] 3d¹⁰ 4s² 4p⁴',[2,8,18,6]],['Br','برم',17,4,'nonmetal','[Ar] 3d¹⁰ 4s² 4p⁵',[2,8,18,7]],['Kr','کریپتون',18,4,'nonmetal','[Ar] 3d¹⁰ 4s² 4p⁶',[2,8,18,8]]
  ];
  registry.periodic={title:'دو عنصر زیر ذره‌بین',chapter:1,pages:'۶ تا ۱۶',mount(container,ctx){
    const defaults={a:11,b:19,target:'a',filter:'all',lens:'radius'},state={...defaults},types={metal:'فلز',nonmetal:'نافلز',metalloid:'شبه‌فلز'};
    container.innerHTML=frame('مقایسهٔ عنصرها',choices('target','انتخاب از جدول برای',[['a','نمونهٔ الف'],['b','نمونهٔ ب']])+choices('filter','نمایش دسته‌ها',[['all','همه'],['metal','فلز'],['nonmetal','نافلز'],['metalloid','شبه‌فلز']])+`<div class="control-group"><span class="control-label">مقایسه‌های کتاب</span><div class="choice-group"><button class="choice-button" type="button" data-action="pair" data-pair="11,19">سدیم و پتاسیم</button><button class="choice-button" type="button" data-action="pair" data-pair="9,17">فلوئور و کلر</button><button class="choice-button" type="button" data-action="pair" data-pair="11,17">سدیم و کلر</button><button class="choice-button" type="button" data-action="pair" data-pair="24,29">کروم و مس</button></div></div><p class="explanation">ابتدا نمونهٔ الف یا ب را انتخاب کنید، سپس روی عنصر دلخواه در جدول بزنید.</p>`, 'دامنه تا عدد اتمی ۳۶ است. حلقه‌ها فقط لایه‌های الکترونی را نشان می‌دهند؛ مدار واقعی یا شعاع مقیاس‌دار نیستند. گردش نمایشی، مسیر واقعی الکترون را نشان نمی‌دهد. برای عناصر دستهٔ d، الکترون‌های بیرونی‌ترین لایه را با همهٔ الکترون‌های ظرفیت یکی نگیرید.');
    container.querySelector('.mt-controls').insertAdjacentHTML('afterbegin',choices('lens','مقایسهٔ دیداری',[['radius','شعاع اتمی'],['metallic','خصلت فلزی و نافلزی']]));
    const bookRadii={Li:152,Na:186,K:231,Mg:160,Ca:197,F:71,Cl:99,Br:114};
    function atom(z,x,label){const e=elementRows[z-1],shells=e[6];let body=txt(x,25,label+' · '+e[1],'mt-svg-title');shells.forEach((count,i)=>{const r=26+i*22;body+=`<circle cx="${x}" cy="145" r="${r}" pathLength="1" class="mt-shell mt-shell-reveal" style="--stagger:${i*85}ms"/>`;let electrons='';for(let j=0;j<count;j++){const angle=j*Math.PI*2/count+i*.3;electrons+=`<circle cx="${x+Math.cos(angle)*r}" cy="${145+Math.sin(angle)*r}" r="3.2" class="mt-electron"/>`;}body+=`<g class="mt-electron-orbit" style="transform-origin:${x}px 145px;--orbit-time:${12+i*4}s;--stagger:${i*85}ms">${electrons}</g>`;});body+=sequence(`<circle cx="${x}" cy="145" r="21" class="mt-carbon"/>`+txt(x,152,e[0],'mt-atom-letter'),0,'mt-build-atom')+txt(x,265,e[5],'mt-svg-small')+txt(x,290,shells.join(' · '),'mt-svg-small');return body;}
    function trend(a,b){
      if(a[0]===b[0])return'هر دو نمونه یک عنصرند؛ عدد اتمی و آرایش آن‌ها یکسان است.';
      if(a[2]===b[2]){const lower=a[3]>b[3]?a:b;return`هر دو در گروه ${ctx.fa(a[2],0)} هستند. ${lower[1]} لایه‌های بیشتری دارد؛ در روند این گروه شعاع رو به پایین افزایش می‌یابد.${a[0]==='H'||b[0]==='H'?' هیدروژن نافلز است و جزء فلزهای قلیایی نیست.':a[2]===1?' در فلزهای قلیایی، واکنش‌پذیری رو به پایین بیشتر است.':a[2]===17?' در هالوژن‌ها، واکنش‌پذیری رو به پایین کمتر است.':''}`;}
      if(a[3]===b[3]&&a[2]<18&&b[2]<18&&(a[2]<=2||a[2]>=13)&&(b[2]<=2||b[2]>=13)){const right=a[2]>b[2]?a:b;return`این دو در دورهٔ ${ctx.fa(a[3],0)} هستند. در روند کلی عناصر اصلی دوره، به سمت ${right[1]} خصلت فلزی کاهش و کشش هسته بر الکترون‌های همان لایه افزایش می‌یابد؛ شعاع عموماً کوچک‌تر می‌شود.`;}
      return'این دو مقایسهٔ سادهٔ «یک گروه» یا «یک دوره از عناصر اصلی» نیستند. تعداد لایه، عدد اتمی و آرایش را جدا بررسی کنید؛ از یک قاعدهٔ ساده سرعت واکنش پیش‌بینی نمی‌شود.';
    }
    const update=()=>{
      const a=elementRows[state.a-1],b=elementRows[state.b-1],sameGroup=a[2]===b[2],samePeriod=a[3]===b[3];
      let table='<div class="mt-periodic-scroll" tabindex="0" role="region" aria-label="جدول دوره‌ای تا عدد اتمی ۳۶؛ پیمایش افقی"><div class="mt-periodic-grid">';for(let g=1;g<=18;g++)table+=`<span class="mt-group-number" style="grid-row:1;grid-column:${g}">${g}</span>`;
      elementRows.forEach((e,i)=>{const selected=i+1===state.a||i+1===state.b,dim=state.filter!=='all'&&state.filter!==e[4];table+=`<button type="button" class="mt-element ${selected?'mt-element-active':''} ${dim?'mt-element-muted':''}" style="grid-row:${e[3]+1};grid-column:${e[2]}" data-action="element" data-z="${i+1}" aria-label="${e[1]}، عدد اتمی ${i+1}، ${types[e[4]]}" aria-pressed="${selected}"><span>${i+1}</span><strong>${e[0]}</strong><small>${types[e[4]]}</small></button>`;});table+='</div></div><p class="mt-hint mt-scroll-hint">جدول را می‌توانید افقی پیمایش کنید. شمارهٔ گروه‌ها در بالا است.</p>';
      container.querySelector('.mt-scene').innerHTML=table+svg('آرایش لایه‌ای دو اتم انتخاب‌شده',atom(state.a,160,'الف')+atom(state.b,460,'ب'),310,'mt-periodic-scene');
      const detail=(e,z,label)=>`<section class="mt-element-detail"><h3>${label}: ${e[1]} ${bdi(e[0])}</h3><dl><div><dt>عدد اتمی</dt><dd>${ctx.fa(z,0)}</dd></div><div><dt>گروه / دوره</dt><dd>${ctx.fa(e[2],0)} / ${ctx.fa(e[3],0)}</dd></div><div><dt>دسته</dt><dd>${types[e[4]]}</dd></div><div><dt>الکترون لایهٔ بیرونی</dt><dd>${ctx.fa(e[6].at(-1),0)}</dd></div></dl></section>`;
      container.querySelector('.mt-result').innerHTML=`<div class="mt-element-details">${detail(a,state.a,'الف')}${detail(b,state.b,'ب')}</div><p class="mt-proof">${trend(a,b)}</p>${[24,29].includes(state.a)||[24,29].includes(state.b)?'<p class="explanation">کروم و مس استثناهای مهم آرایش‌اند: Cr دارای 3d⁵4s¹ و Cu دارای 3d¹⁰4s¹ است.</p>':''}`;
      if(state.lens==='radius'){
        const measured=sameGroup&&bookRadii[a[0]]&&bookRadii[b[0]],mainPeriod=samePeriod&&a[2]<18&&b[2]<18&&(a[2]<=2||a[2]>=13)&&(b[2]<=2||b[2]>=13),qualitative=!measured&&a!==b&&(sameGroup||mainPeriod);
        let ra=100,rb=100;if(measured){ra=bookRadii[a[0]]/231*160;rb=bookRadii[b[0]]/231*160;}else if(qualitative){const aLarger=sameGroup?a[3]>b[3]:a[2]<b[2];ra=aLarger?145:95;rb=aLarger?95:145;}
        const atomRadius=(e,d,label)=>`<div class="mt-radius-sample"><h4>${label}: ${e[1]}</h4><div class="mt-radius-space"><div class="mt-radius-disc" style="--atom-diameter:${d}px" data-radius="${measured?bookRadii[e[0]]:'qualitative'}"><span>${e[0]}</span><i aria-hidden="true"></i></div></div><strong>${measured?bdi(ctx.fa(bookRadii[e[0]],0)+' pm'):qualitative?'فقط مقایسهٔ کیفی':'اندازهٔ مقایسه‌ای تعیین نشده'}</strong></div>`;
        container.querySelector('.mt-result').innerHTML+=analysis(measured?'شعاع‌ها با مقیاس مشترک':'شعاع: روند را از اندازه جدا کن',`<div class="mt-radius-pair">${atomRadius(a,ra,'الف')}${atomRadius(b,rb,'ب')}</div><p class="mt-comparison-conclusion">${measured?'نسبت شعاع الف به ب: '+ctx.fa(bookRadii[a[0]]/bookRadii[b[0]],2)+'؛ قطر دو دایره با داده‌های کتاب متناسب است.':qualitative?'بزرگی نسبی از روند کتاب است؛ نسبت اندازهٔ دایره‌ها عدد تجربی نیست.':a===b?'دو انتخاب یک عنصرند.':'برای این جفت، قاعدهٔ سادهٔ گروه/دوره یا دادهٔ عددی هم‌سنخ در این ابزار نداریم.'}</p>`, measured?'اعداد صفحه‌های ۱۲ و ۱۳ کتاب؛ شعاع فلزی برای Li/Na/K و Mg/Ca، شعاع کووالانسی برای F/Cl/Br. هر مقایسهٔ عددی در یک گروه و با تعریف یکسان انجام می‌شود.':'دایره‌های این بخش مدار الکترونی نیستند. برای عددهای مستقیم کتاب، سدیم–پتاسیم یا فلوئور–کلر را انتخاب کنید.');
      }else{
        let map=txt(310,25,'جهت روند کلی؛ بدون مقیاس عددی','mt-svg-small');
        for(let p=1;p<=4;p++)for(let g=1;g<=18;g++)map+=`<circle cx="${55+(g-1)*30}" cy="${55+(p-1)*40}" r="2" class="mt-period-position"/>`;
        map+=`<path d="M570,42 H35 V190 l-7,-12 M35,190 l7,-12" class="mt-metal-direction"/><path d="M42,35 H575 l-12,-7 M575,35 l-12,7" class="mt-nonmetal-direction"/>`+txt(310,218,'خصلت فلزی: رو به چپ و پایین بیشتر','mt-svg-small');
        [[a,'الف','a'],[b,'ب','b']].forEach(([e,label,c],i)=>{const x=55+(e[2]-1)*30,y=55+(e[3]-1)*40;map+=`<circle cx="${x}" cy="${y}" r="${a===b&&i===0?20:14}" class="mt-map-atom mt-series-${c}"/>`+txt(x,y+5,e[0],'mt-map-symbol')+txt(x,Math.min(204,y+30),label,'mt-svg-small');});
        const metallicOrder=a===b?'دو نمونه یکسان‌اند.':sameGroup&&a[2]!==18&&a[0]!=='H'&&b[0]!=='H'?`در این گروه، ${a[3]>b[3]?a[1]:b[1]} پایین‌تر است و در روند کلی خصلت فلزی بیشتری دارد.`:samePeriod&&a[2]<18&&b[2]<18&&(a[2]<=2||a[2]>=13)&&(b[2]<=2||b[2]>=13)?`در این دوره، ${a[2]<b[2]?a[1]:b[1]} به سمت فلزی‌تر و ${a[2]>b[2]?a[1]:b[1]} به سمت نافلزی‌تر قرار دارد.`:'برای این جفت، دسته‌بندی هر عنصر را بخوانید؛ این جهت کلی برای رتبه‌بندی کمی یا پیش‌بینی سرعت واکنش کافی نیست.';
        container.querySelector('.mt-result').innerHTML+=analysis('جای عنصر و گرایش فلزی',legend('الف: '+types[a[4]],'ب: '+types[b[4]])+svg('جای دو عنصر روی نقشهٔ گروه و دوره، همراه جهت کلی تغییر خصلت فلزی',map,235,'mt-metal-map')+`<p class="mt-comparison-conclusion">${metallicOrder}</p>`, 'شمارهٔ گروه از چپ به راست و دوره از بالا به پایین زیاد می‌شود. نافلزی بودن عموماً به سمت راست و بالا بیشتر است؛ گازهای نجیب و جزئیات فلزهای واسطه را با این قاعده رتبه‌بندی نمی‌کنیم. هیدروژن فلز قلیایی نیست.');
      }
    };
    return bind(container,ctx,state,defaults,update,()=>ctx.saveRecord({title:'مقایسهٔ '+elementRows[state.a-1][1]+' و '+elementRows[state.b-1][1],tool:'periodic',summary:trend(elementRows[state.a-1],elementRows[state.b-1]),values:[{label:'آرایش الف',value:elementRows[state.a-1][5],unit:''},{label:'آرایش ب',value:elementRows[state.b-1][5],unit:''}],note:'شکل لایه‌ها شماتیک است.'}),(key,value,b)=>{if(key==='action'&&value==='element')state[state.target]=Number(b.dataset.z);if(key==='action'&&value==='pair'){const pair=b.dataset.pair.split(',').map(Number);state.a=pair[0];state.b=pair[1];}});
  }};
})();
